class M:
 def __str__(self):
  print("format")
  raise LookupError("broken")
e=ValueError(M())
print("made")
try: str(e)
except LookupError: print("caught")

class M:
 def __repr__(self):
  print("bad")
  return "m"
e=RuntimeError(M(),M())
print(len(e.args))

m=[]
try: assert False,m
except AssertionError as e: print(e.args[0] is m)

class M:
 def __str__(self):
  print("bad")
  return "m"
m=M()
try: assert False,m
except AssertionError as e: print(e.args[0] is m)

class I:
 def __iter__(self):
  yield 7
  raise ValueError("broken")
e=Exception(9)
t=e.args
try: e.args=I()
except ValueError: print(e.args is t,e.args[0])

e=Exception(9)
try: e.args=7
except TypeError: print(e.args[0])

outer=ValueError("outer")
try:
 try: raise outer
 except ValueError: raise TypeError("inner")
except TypeError as e: print(e.__context__ is outer,e.__cause__ is None,e.__suppress_context__)

a=LookupError()
try:
 try: raise a
 except LookupError: raise ValueError() from None
except ValueError as e: print(e.__context__ is a,e.__cause__ is None,e.__suppress_context__)

def e():
 print("exception")
 return ValueError()
def c():
 print("cause")
 return None
try: raise e() from c()
except ValueError: print("caught")

def c():
 raise LookupError("cause failed")
raise ValueError("error") from c()

c=TypeError()
def f():
 try: raise ValueError("x") from c
 except ValueError: raise
try: f()
except ValueError as e: print(e.__cause__ is c,e.__suppress_context__)

try:
 try: raise ValueError() from None
 finally: print("finally")
except ValueError: print("caught")

a=ValueError()
b=TypeError()
try:
 try: raise a
 except ValueError:
  try: raise b
  except TypeError: raise a
except ValueError as e: print(e is a,a.__context__ is b,b.__context__ is None)

e=ValueError()
try: raise e from e
except ValueError as caught: print(caught.__cause__ is caught,caught.__context__ is None)

def fail():
 raise ValueError("x") from TypeError("y")
def middle():
 try: fail()
 except ValueError: raise
middle()

class E(Exception):
 def __new__(cls,x):
  print("new")
  e=super().__new__(cls,x)
  e.saved=x
  return e
 def __init__(self,x):
  print("init",self.saved is x,self.args[0] is x)
e=E([])
print(type(e) is E)

class E(Exception):
 def __new__(cls): return []
 def __init__(self): print("bad")
e=E()
print(type(e) is list)

class E(Exception):
 def __new__(cls): return object.__new__(cls)
E()

class E(Exception):
 @property
 def args(self): return (9,)
e=E(7)
print(e.args[0],BaseException.args.__get__(e)[0],str(e))

class E(Exception):
 def __init__(self): return 7
E()

class E(Exception):
 def __init__(self):
  print("init")
  super().__init__(7)
try: raise E
except E as e: print(type(e) is E,e.args[0])

class E(ValueError,TypeError): pass
try: raise E(7)
except TypeError as e: print(type(e) is E,e.args[0])

class E(Exception): pass
class F(Exception): pass
try: raise E(7)
except (ValueError,F): print("bad")
except (TypeError,E) as e: print(e.args[0])

class E(Exception): pass
class F(Exception): pass
g=globals()
g["Handler"]=E
try: raise E(7)
except (F,Handler) as e: print(e.args[0])

class E(Exception):
 def __init__(self): print("error init")
class C(Exception):
 def __init__(self): print("cause init")
def error():
 print("error expression")
 return E
def cause():
 print("cause expression")
 return C
try: raise error() from cause()
except E as e: print(type(e.__cause__) is C,e.__suppress_context__)

class E(Exception):
 def __init__(self): raise LookupError("failed")
try: raise E
except LookupError as e: print(str(e))

class C(Exception):
 def __init__(self): raise LookupError("cause failed")
try: raise ValueError() from C
except LookupError as e: print(str(e))

class E(Exception):
 def __new__(cls): return []
raise E

class C(Exception):
 def __new__(cls): return []
raise ValueError() from C

class E(Exception):
 def __new__(cls): return ValueError
raise E

class C(Exception):
 def __new__(cls): return ValueError
raise ValueError() from C

class E: pass
try: raise ValueError()
except E: pass

bad=7
try: raise ValueError()
except (bad,missing): pass

class M(type):
 def __subclasscheck__(cls,other):
  print("bad")
  return True
class E(Exception,metaclass=M): pass
try: raise ValueError()
except E: print("bad")
except ValueError: print("native")

class E(Exception): pass
e=E(7)
def f():
 try: raise e
 except E: raise
 finally: print("finally")
try: f()
except E as caught: print(caught is e,caught.__context__ is None)

class E(Exception): pass
def g():
 try:
  yield 7
  raise E(8) from None
 finally: print("closed")
i=g()
print(next(i))
try: next(i)
except E as e: print(e.args[0],e.__suppress_context__)

class E(ValueError): pass
def fail():
 raise E(7) from None
def middle():
 try: fail()
 except E: raise
middle()
